package main
import("context";"encoding/json";"errors";"flag";"fmt";"log";"net";"net/http";"os";"os/signal";"path/filepath";"sync";"syscall";"time")
const version="v0.1.1"
type Module struct{ID string `json:"id"`;Name string `json:"name"`;Status string `json:"status"`;LastCheck string `json:"lastCheck"`;Items int `json:"items"`}
type Snapshot struct{Version string `json:"version"`;UpdatedAt string `json:"updatedAt"`;Modules []Module `json:"modules"`;Opportunities []any `json:"opportunities"`;Demo bool `json:"demo"`}
type Engine struct{mu sync.RWMutex;state Snapshot;path string}
func newEngine(path string)*Engine{e:=&Engine{path:path,state:Snapshot{Version:version,Opportunities:[]any{},Modules:[]Module{{ID:"products",Name:"商品套利",Status:"awaiting_source"},{ID:"government",Name:"政府采购",Status:"awaiting_source"},{ID:"business",Name:"企业商机",Status:"awaiting_source"},{ID:"finance",Name:"金融市场",Status:"awaiting_source"}}}};if b,err:=os.ReadFile(path);err==nil{var s Snapshot;if json.Unmarshal(b,&s)==nil&&s.Version==version{e.state=s}};return e}
func(e *Engine)snapshot()Snapshot{e.mu.RLock();defer e.mu.RUnlock();return e.state}
func(e *Engine)tick()error{e.mu.Lock();defer e.mu.Unlock();e.state.UpdatedAt=time.Now().UTC().Format(time.RFC3339);for i:=range e.state.Modules{e.state.Modules[i].LastCheck=e.state.UpdatedAt};b,err:=json.MarshalIndent(e.state,"","  ");if err!=nil{return err};if err=os.MkdirAll(filepath.Dir(e.path),0700);err!=nil{return err};tmp:=e.path+".tmp";if err=os.WriteFile(tmp,b,0600);err!=nil{return err};return os.Rename(tmp,e.path)}
func main(){addr:=flag.String("listen","127.0.0.1:14236","local dashboard address");data:=flag.String("data",filepath.Join("data","state.json"),"local state path");flag.Parse();host,_,err:=net.SplitHostPort(*addr);if err!=nil{log.Fatal(err)};ip:=net.ParseIP(host);if ip==nil||!ip.IsLoopback(){log.Fatal("dashboard must bind to loopback only")};e:=newEngine(*data);if err=e.tick();err!=nil{log.Fatal(err)};mux:=http.NewServeMux();mux.HandleFunc("GET /api/status",func(w http.ResponseWriter,r *http.Request){w.Header().Set("Content-Type","application/json; charset=utf-8");w.Header().Set("Cache-Control","no-store");_=json.NewEncoder(w).Encode(e.snapshot())});mux.HandleFunc("GET /",func(w http.ResponseWriter,r *http.Request){if r.URL.Path!="/"{http.NotFound(w,r);return};w.Header().Set("Content-Type","text/html; charset=utf-8");_,_=w.Write([]byte(indexHTML))});server:=&http.Server{Addr:*addr,Handler:mux,ReadHeaderTimeout:5*time.Second};ctx,stop:=signal.NotifyContext(context.Background(),os.Interrupt,syscall.SIGTERM);defer stop();go func(){t:=time.NewTicker(30*time.Second);defer t.Stop();for{select{case <-ctx.Done():return;case <-t.C:if err:=e.tick();err!=nil{log.Printf("persist state: %v",err)}}}}();go func(){<-ctx.Done();c,cancel:=context.WithTimeout(context.Background(),5*time.Second);defer cancel();_=server.Shutdown(c)}();fmt.Printf("OpportunityRadar %s running at http://%s\n",version,*addr);if err:=server.ListenAndServe();err!=nil&&!errors.Is(err,http.ErrServerClosed){log.Fatal(err)}}
